<template>
 <section class="career-page" v-loading="busy">
  <div class="career-breadcrumb"><el-button link @click="emit('back')">{{backLabel}}</el-button><span>/ 球员生涯</span><el-button class="refresh" :loading="busy" @click="refresh">刷新档案</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="refresh">重新读取</el-button></el-alert>
  <template v-if="data">
   <header class="career-hero"><img v-if="logo" :src="logo" class="career-watermark" alt="" @error="logo=''"/><div class="career-identity"><small class="career-eyebrow">PLAYER PROFILE</small><h1>{{p.name||'姓名待完善'}}</h1><div class="career-tags"><span>{{p.position||'位置未登记'}}</span><span v-if="p.jerseyNumber!=null">#{{p.jerseyNumber}}</span><span>{{cardTier}}</span></div><div class="career-bio"><span><small>国籍</small>{{p.nationality||'—'}}</span><span><small>年龄</small>{{age==null?'—':age+' 岁'}}</span><span><small>身高</small>{{p.height==null?'—':p.height+' cm'}}</span></div><div class="career-current-team"><img v-if="logo" :src="logo" alt="当前队徽"/><div><small>当前所属球队</small><strong>{{data.currentTeam?.name||'未关联球队'}}</strong></div></div></div><img v-if="portrait" :src="portrait" class="career-portrait" alt="球员形象" @error="portrait=''"/><div class="career-valuation"><div class="career-value-label">转会评估身价<span v-if="!v.minor&&v.tier">{{v.tier}} {{v.tierValue}}</span></div><strong class="career-value">{{v.minor?'仅展示星级':v.coverage==='complete'&&v.moneyText?v.moneyText:'待评估'}}</strong><div class="career-valuation-meta"><span v-if="!v.minor">总评估值 {{metric(v.total)}}</span><span v-if="!v.minor" :title="trendHint" :class="'career-trend-flag '+trendClass">走势 {{trendFlag}}</span><span>同组别 {{v.stars==null?'待评估':v.stars.toFixed(1)+' / 5 星'}}</span></div><p>评估参考值，不是成交价</p><small v-if="v.estimated?.length" class="career-estimated">含 {{v.estimated.length}} 项估计因子</small></div></header>
   <nav class="career-nav"><a href="#career-overview" @click.prevent="jump('career-overview')">数据总览</a><a href="#career-five" @click.prevent="jump('career-five')">五维表现</a><a href="#career-matches" @click.prevent="jump('career-matches')">比赛记录</a><a href="#career-transfers" @click.prevent="jump('career-transfers')">转会记录</a><el-button class="career-audit" type="primary" @click="emit('audit',playerId)">核验资料</el-button></nav>
   <div class="career-grid"><aside class="career-sidebar"><div class="career-card-stage"><img v-if="cardUrl" :src="cardUrl" alt="完整球员卡" @error="cardUrl='';cardError='成卡图片读取失败，请重试'" @click="preview=true"/><div v-else class="career-card-empty"><span>{{cardBusy?'正在读取球员卡':cardError||'暂无可用成卡'}}</span><el-button v-if="!cardBusy" link @click="loadCard">重新读取</el-button></div></div><div class="career-sidebar-content"><h3>生涯积分</h3><strong class="career-points">{{metric(data.statistics.playerCard?.points)}}<small> 分</small></strong><p class="career-muted">{{cardTier}} · 与身价独立</p><h3>基本资料</h3><dl class="career-facts"><dt>球员编号</dt><dd>{{numberLabel(p)}}<el-button v-if="!p.businessNumber" link @click="numberingRef.open(p,'players')">补发编号</el-button></dd><dt>球衣名</dt><dd>{{p.jerseyName||'—'}}</dd><dt>籍贯</dt><dd>{{p.nativePlace||'—'}}</dd><dt>出生日期</dt><dd>{{dateText(p.birthday)}}</dd><dt>身高 / 体重</dt><dd>{{p.height??'—'}} / {{p.weight??'—'}} kg</dd><dt>当前所属球队</dt><dd>{{data.currentTeam?.name||'—'}}</dd><dt>入驻平台</dt><dd>{{dateText(p.registration?.registeredAt)}}</dd><dt>档案创建</dt><dd>{{dateText(p.registration?.profileCreatedAt)}}</dd></dl><p class="career-muted">首次入驻没有独立证据时显示 —。</p></div></aside>
   <div class="career-content"><section class="career-panel" id="career-overview"><div class="career-panel-head"><h2>职业生涯</h2><span>平台授权范围 · 正式赛果</span></div><div class="career-stats"><div v-for="field in fields" :key="field.key"><strong>{{metric(metrics[field.key])}}</strong><small>{{field.label}}</small></div></div><div class="career-panel-foot"><span>{{data.statistics.coverage?.status==='complete'?'记录完整':'部分记录待核验'}}</span><span>{{dateText(data.generatedAt)}} 更新</span></div></section>
   <div class="career-two"><section class="career-panel" id="career-five"><div class="career-panel-head"><h2>五维表现</h2><span>{{data.five.status==='complete'?'已核定':'部分维度待核验'}}</span></div><div class="career-radar-row"><svg viewBox="0 0 300 260" class="career-radar" role="img" aria-label="五维赛事表现"><polygon v-for="level in [0.25,0.5,0.75,1]" :key="level" :points="polygon(level)" fill="none" stroke="#dfe9e2"/><line v-for="(axis,i) in axes" :key="axis.key" x1="150" y1="130" :x2="point(i,1).x" :y2="point(i,1).y" stroke="#e3eae5"/><polygon v-if="scorePoints.length>=3" :points="scorePolygon" fill="#087a4824" stroke="#087a48" stroke-width="2"/><circle v-for="sp in scorePoints" :key="sp.i" :cx="sp.x" :cy="sp.y" r="4" fill="#087a48"/><template v-for="(axis,i) in axes" :key="axis.key"><text :x="point(i,1.25).x" :y="point(i,1.25).y+4" text-anchor="middle" fill="#7e9384" font-size="10">{{axis.label}}</text></template><text v-if="axes.some(a=>a.score==null)" x="150" y="134" text-anchor="middle" fill="#99a99d" font-size="11">记录待补齐</text></svg><div class="career-axis-values"><div v-for="axis in axes" :key="axis.key"><label>{{axis.label}}</label><strong>{{axis.score==null?'待核验':axis.score.toFixed(1)}}<small class="career-axis-scale"> /10</small></strong><small v-if="axis.raw!=null">{{axis.raw}} {{axis.unit}}</small><small v-else>{{axis.unit}}</small></div></div></div><p class="career-muted">五维为 0–10 分，未核定维度不填补、不补 0。</p></section>
   <section class="career-panel"><div class="career-panel-head"><h2>身价走势</h2><span>历史评估快照</span></div><template v-if="snapshots.length>1&&!v.minor"><svg class="career-trend" viewBox="0 0 400 215" role="img" aria-label="身价历史"><line v-for="y in [30,80,130,180]" :key="y" x1="20" x2="380" :y1="y" :y2="y" stroke="#e6ece7" stroke-dasharray="3 4"/><polyline :points="trendPoints" fill="none" stroke="#ba9a56" stroke-width="2.5"/><circle v-for="(s,i) in snapshots" :key="s.id" :cx="trendPoint(s,i).x" :cy="trendPoint(s,i).y" r="3" fill="#ba9a56"/></svg><div class="career-trend-dates"><span>{{dateText(snapshots[0].computedAt)}}</span><span>{{dateText(snapshots.at(-1).computedAt)}}</span></div></template><div v-else class="career-empty">{{v.minor?'青少年不展示金额走势':'暂无可比较的有效身价快照'}}</div><p class="career-muted">只使用已留存快照，不回推历史身价。</p></section></div>
   <section class="career-panel" id="career-matches"><div class="career-panel-head"><h2>比赛记录</h2><span>生涯正式比赛</span></div><el-table :data="matchPage" empty-text="暂无可核定的比赛记录"><el-table-column label="日期" min-width="100"><template #default="{row}">{{dateText(row.date)}}</template></el-table-column><el-table-column prop="tournamentName" label="赛事" min-width="140"/><el-table-column label="当时球队" min-width="130"><template #default="{row}">{{row.teamNames?.join('、')||'—'}}</template></el-table-column><el-table-column prop="matchName" label="对阵" min-width="190"/><el-table-column label="比分" width="80"><template #default="{row}">{{row.homeScore==null||row.awayScore==null?'—':row.homeScore+' : '+row.awayScore}}</template></el-table-column><el-table-column label="分钟" width="75"><template #default="{row}">{{metric(row.minutesPlayed)}}</template></el-table-column><el-table-column label="进球" width="70"><template #default="{row}">{{metric(row.goals)}}</template></el-table-column></el-table><el-pagination v-if="data.recentMatches.length>10" v-model:current-page="matchIndex" :page-size="10" :total="data.recentMatches.length" layout="prev,pager,next,total"/></section>
   <section class="career-panel" id="career-transfers"><div class="career-panel-head"><h2>转会记录</h2><span>业务记录与历史归属分开展示</span></div><div v-if="!data.transfers.items.length" class="career-empty compact">暂无已确认的转会业务记录</div><div v-for="t in data.transfers.items" :key="t.id" class="career-transfer-row"><div><strong>{{dateText(t.effectiveAt||t.requestedAt)}}</strong><small>{{t.effectiveAt?'转会生效':'申请时间'}}</small></div><div class="career-transfer-route"><span>{{teamName(t.fromTeamId)}}</span><b>→</b><strong>{{teamName(t.toTeamId)}}</strong><small v-if="!v.minor">当期评估 {{t.valuationSnapshot?money(t.valuationSnapshot.money):'未留存'}}</small></div><span>{{transferState(t.status)}}</span></div><h3 v-if="data.memberships.items.length" class="career-subtitle">效力球队历史</h3><el-alert v-if="data.memberships.status==='conflict'" title="球队关系存在冲突，须核验后确认归属" type="warning" :closable="false"/><el-table v-if="data.memberships.items.length" :data="data.memberships.items"><el-table-column label="球队" min-width="150"><template #default="{row}">{{teamName(row.teamId)}}</template></el-table-column><el-table-column label="加入日期"><template #default="{row}">{{dateText(row.joinedAt)}}</template></el-table-column><el-table-column label="离队日期"><template #default="{row}">{{row.endState==='open'?'未记录离队':dateText(row.leftAt)}}</template></el-table-column></el-table><p class="career-muted">首次入驻不是转会；没有历史记录不代表从未转队。</p></section>
   <div class="career-two"><section class="career-panel"><div class="career-panel-head"><h2>身价评估构成</h2><span>现行八项因子</span></div><div class="career-factors"><div v-for="f in factorFields" :key="f.key"><div><span>{{f.label}} <small v-if="v.estimated?.includes(f.key)">估计</small></span><b>{{v.factors?.[f.key]==null?'—':Math.round(v.factors[f.key]*100)+' / 100'}}</b></div><div class="career-factor-track"><i :style="{width:v.factors?.[f.key]==null?'0%':v.factors[f.key]*100+'%'}" :class="{estimated:v.estimated?.includes(f.key)}"/></div></div></div></section><section class="career-panel"><div class="career-panel-head"><h2>荣誉记录</h2><span>已归档正式赛事系统评定</span></div><div v-if="!honors.length" class="career-empty">暂无已归档正式奖项</div><div v-else class="career-honors"><div v-for="h in honors" :key="h.id" class="career-honor"><strong>{{h.title}}</strong><span>{{h.tournamentName||'赛事待核验'}} · {{h.divisionName||'未分组别'}}</span><small>{{honorNote(h)}}</small><small v-if="h.manual" class="career-honor-manual">主办方手动调整</small></div></div></section></div>
   <details class="career-version"><summary>数据版本与完整度</summary><p>数据 {{data.dataVersion}} · 指标 {{data.statistics.metricVersion}}</p><p>来源问题 {{data.statistics.issues?.length??0}} 项 · 球队关系 {{data.memberships.issues?.length??0}} 项</p></details>
   </div></div>
  </template>
  <NumberingDialog ref="numberingRef" @changed="refresh"/>
  <el-dialog v-model="preview" title="球员卡" width="min(420px,94vw)"><img v-if="cardUrl" :src="cardUrl" alt="完整成卡" style="width:300px;max-width:100%;display:block;margin:auto"/></el-dialog>
 </section>
</template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {getFileUrl,playerCardTemplateRequest} from '../../utils/cloud'
import {dataHub,dateText,metric,safeImage,numberLabel} from './dataHubApi'
import './career.css'
import NumberingDialog from './NumberingDialog.vue'
const props=defineProps({playerId:{type:String,required:true},backLabel:{type:String,default:'返回目录'}}),emit=defineEmits(['back','audit'])
const data=ref(null),busy=ref(false),error=ref(''),logo=ref(''),portrait=ref(''),cardUrl=ref(''),cardBusy=ref(false),cardError=ref(''),preview=ref(false),matchIndex=ref(1)
const numberingRef=ref(null)
let seq=0,cardSeq=0
const p=computed(()=>data.value?.profile||{}),v=computed(()=>data.value?.statistics?.valuation||{}),metrics=computed(()=>data.value?.statistics?.playerTotal?.metrics||{}),axes=computed(()=>data.value?.five?.axes||[])
const trendComparable=computed(()=>v.value.historyStatus==='recorded')
const trendFlag=computed(()=>{if(v.value.minor)return '';if(!trendComparable.value)return '—';return ['↑','↓','→'].includes(v.value.trendArrow)?v.value.trendArrow:'—'})
const trendClass=computed(()=>!trendComparable.value?'none':({up:'up',down:'down',flat:'flat'}[v.value.trendTone]||'flat'))
const trendHint=computed(()=>trendComparable.value?'与上一份有效身价快照比较，±2% 内记为持平':'暂无可比较的有效身价快照，历史身价不回推')
const fields=[{key:'appearances',label:'出场场次'},{key:'starts',label:'首发场次'},{key:'minutesPlayed',label:'出场分钟'},{key:'goals',label:'进球'},{key:'assists',label:'助攻'},{key:'yellowCards',label:'黄牌'},{key:'redCards',label:'红牌'}]
const factorFields=[{key:'core',label:'竞技基线'},{key:'age',label:'年龄潜力'},{key:'quality',label:'表现质量'},{key:'appearance',label:'出场稳定'},{key:'scarcity',label:'位置稀缺'},{key:'tier',label:'赛事级别'},{key:'trend',label:'成长趋势'},{key:'card',label:'卡种与应援'}]
const cardTier=computed(()=>({bronze:'铜卡',silver:'银卡',gold:'金卡'}[data.value?.statistics?.playerCard?.tier]||'等级待核验'))
const age=computed(()=>{if(!p.value.birthday)return null;const born=new Date(p.value.birthday),now=new Date();let years=now.getFullYear()-born.getFullYear();if(now.getMonth()<born.getMonth()||now.getMonth()===born.getMonth()&&now.getDate()<born.getDate())years--;return years>=0&&years<=100?years:null})
const snapshots=computed(()=>data.value?.snapshots?.items.filter(s=>Number.isFinite(s.money))||[]),matchPage=computed(()=>data.value?.recentMatches.slice((matchIndex.value-1)*10,matchIndex.value*10)||[])
const teamName=id=>data.value?.teams.find(t=>t.id===id)?.name||'历史球队资料待核验',money=value=>Number.isFinite(value)?'¥'+value.toLocaleString('zh-CN'):'未留存'
const transferState=s=>({accepted:'已完成',pending:'待确认',rejected:'已拒绝',cancelled:'已取消'}[s]||'状态待核验')
function point(i,ratio){return {x:150+Math.sin(i*Math.PI*2/5)*80*ratio,y:130-Math.cos(i*Math.PI*2/5)*80*ratio}}
const polygon=ratio=>Array.from({length:5},(_,i)=>{const p=point(i,ratio);return p.x+','+p.y}).join(' ')
const honors=computed(()=>data.value?.honors||[])
const scorePoints=computed(()=>axes.value.map((a,i)=>{if(a.score==null)return null;const p=point(i,a.score/10);return {i,x:p.x,y:p.y}}).filter(Boolean))
const scorePolygon=computed(()=>scorePoints.value.map(p=>p.x+','+p.y).join(' '))
function honorNote(h){if(h.key==='goalkeeper')return `零封 ${h.cleanSheets==null?'—':h.cleanSheets} 场`;const parts=[`进球 ${h.goals??0}`,`助攻 ${h.assists??0}`];if(h.key==='mvp')parts.push(`贡献分 ${h.contribution??0}`);if(h.key==='bestXI')parts.push(h.slot||'入选');return parts.join(' · ')}
function trendPoint(s,i){const values=snapshots.value.map(x=>x.money),min=Math.min(...values),max=Math.max(...values);return {x:20+i*360/(values.length-1||1),y:180-(s.money-min)*150/(max-min||1)}}
const trendPoints=computed(()=>snapshots.value.map((s,i)=>{const p=trendPoint(s,i);return p.x+','+p.y}).join(' '))
function jump(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
async function loadCard(){const s=++cardSeq;cardBusy.value=true;cardError.value='';cardUrl.value='';portrait.value='';try{const r=await playerCardTemplateRequest('getPlayerCardForViewer',{playerId:props.playerId,playerCardRendererVersion:'player-card-web/2'},{cache:'reload'});if(s!==cardSeq)return;if(!r.success||r.status==='forbidden')throw new Error(r.error||'当前无法读取球员卡');cardUrl.value=safeImage(r.cardUrl);const scenePortrait=safeImage(r.cardScene?.assets?.portrait);if(scenePortrait)portrait.value=scenePortrait;if(!cardUrl.value)cardError.value=r.cardError||({pending:'球员卡更新中',unavailable:'暂无可用成卡'}[r.status]||'成卡暂不可用')}catch(e){if(s===cardSeq)cardError.value=e.message}finally{if(s===cardSeq)cardBusy.value=false}}
async function refresh(){const s=++seq;busy.value=true;error.value='';data.value=null;logo.value='';matchIndex.value=1;loadCard();try{const r=await dataHub('hubPlayerProfile',{playerId:props.playerId});if(s!==seq)return;data.value=r;getFileUrl(r.currentTeam?.logo||'').then(img=>{if(s===seq)logo.value=safeImage(img)}).catch(()=>{});if(r.portraitSource)getFileUrl(r.portraitSource).then(img=>{if(s===seq&&!portrait.value)portrait.value=safeImage(img)}).catch(()=>{})}catch(e){if(s===seq)error.value=e.message}finally{if(s===seq)busy.value=false}}
watch(()=>props.playerId,refresh,{immediate:true});onBeforeUnmount(()=>{seq++;cardSeq++});defineExpose({refresh,loading:busy})
</script>
